101	struct Base58Decode
102	{
103	    static constexpr auto name = "base58Decode";
104	
105	    static void process(const ColumnString & input, ColumnString::MutablePtr & dst_column, const std::string & alphabet, size_t input_rows_count)
106	    {
107	        auto & dst_data = dst_column->getChars();
108	        auto & dst_offsets = dst_column->getOffsets();
109	
110	        /// We allocate probably even more then needed to avoid many resizes
111	        size_t current_allocated_size = input.getChars().size();
112	
113	        dst_data.resize(current_allocated_size);
114	        dst_offsets.resize(input_rows_count);
115	
116	        const ColumnString::Offsets & src_offsets = input.getOffsets();
117	
118	        const auto * source = input.getChars().raw_data();
119	        auto * dst = dst_data.data();
120	        auto * dst_pos = dst;
121	
122	        size_t src_offset_prev = 0;
123	        size_t processed_size = 0;
124	
125	        const auto& decoder = (alphabet == "bitcoin") ? Base58::bitcoin() :
126	                             ((alphabet == "flickr") ? Base58::flickr() :
127	                             ((alphabet == "ripple") ? Base58::ripple() :
128	                                                       Base58::base58()));
129	
130	        std::string decoded;
131	        for (size_t row = 0; row < input_rows_count; ++row)
132	        {
133	            size_t srclen = src_offsets[row] - src_offset_prev - 1;
134	            /// Why we didn't use char* here?
135	            /// We don't know the size of the result string beforehand (it's not byte-to-byte encoding),
136	            /// so we may need to do many resizes (the worst case -- we'll do it for each row)
137	            /// This way we do exponential resizes and one final resize after whole operation is complete
138	            decoded.clear();
139	            if (srclen)
140	                try
141	                {
142	                    decoder.decode(decoded, source, srclen);
143	                }
144	                catch (const std::invalid_argument& e)
145	                {
146	                    throw Exception(e.what(), ErrorCodes::BAD_ARGUMENTS);
147	                }
148	                catch (const std::domain_error& e)
149	                {
150	                    throw Exception(e.what(), ErrorCodes::BAD_ARGUMENTS);
151	                }
152	            size_t outlen = decoded.size();
153	
154	            if (processed_size + outlen >= current_allocated_size)
155	            {
156	                current_allocated_size += current_allocated_size;
157	                dst_data.resize(current_allocated_size);
158	                auto processed_offset = dst_pos - dst;
159	                dst = dst_data.data();
160	                dst_pos = dst;
161	                dst_pos += processed_offset;
162	            }
163	            std::memcpy(dst_pos, decoded.c_str(), ++outlen);
164	
165	            source += srclen + 1;
166	            dst_pos += outlen;
167	
168	            dst_offsets[row] = dst_pos - dst;
169	            src_offset_prev = src_offsets[row];
170	            processed_size += outlen;
171	        }
172	
173	        dst_data.resize(dst_pos - dst);
174	    }
175	};
